'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['entriesToRecord']);
const { entriesToRecord } = api;
assert.strictEqual(typeof entriesToRecord, 'function');

const empty = entriesToRecord([]);
assert.strictEqual(Object.getPrototypeOf(empty), null);
assert.deepStrictEqual(Object.keys(empty), []);

const shared = { value: 1 };
const pair1 = Object.freeze(['first', shared]);
const pair2 = Object.freeze(['__proto__', 7]);
const pair3 = Object.freeze(['', false]);
const pair4 = Object.freeze(['First', undefined]);
const entries = Object.freeze([pair1, pair2, pair3, pair4]);
const result = entriesToRecord(entries);
assert.strictEqual(Object.getPrototypeOf(result), null);
assert.deepStrictEqual(Object.keys(result), ['first', '__proto__', '', 'First']);
assert.strictEqual(result.first, shared);
assert.strictEqual(result.__proto__, 7);
assert.strictEqual(result[''], false);
assert.strictEqual(Object.hasOwn(result, '__proto__'), true);
assert.strictEqual(Object.hasOwn(result, 'First'), true);
assert.strictEqual(result.First, undefined);
assert.deepStrictEqual(entries, [pair1, pair2, pair3, pair4]);

const again = entriesToRecord(entries);
assert.notStrictEqual(again, result);
assert.strictEqual(again.first, shared);
result.added = true;
assert.strictEqual(Object.hasOwn(again, 'added'), false);

assert.throws(() => entriesToRecord([['a', 1], ['a', 2]]), RangeError);
assert.throws(() => entriesToRecord([['__proto__', 1], ['__proto__', 2]]), RangeError);
assert.deepStrictEqual(Object.keys(entriesToRecord([['a', 1], ['A', 2]])), ['a', 'A']);

for (const invalid of [null, undefined, {}, 'x', [null], [[]], [['a']], [['a', 1, 2]], [[1, 'value']], new Array(1)]) {
  assert.throws(() => entriesToRecord(invalid), TypeError);
}

